// Diving finds: shells, seaweed, oysters, mussels and sunken chests on the sea and lake beds, picked or opened while
// swimming. Design: docs/planes/gta/PLAN-D-barras-buceo.md §4.6 (interaction part). The controls and the diver's depth
// are entities.js (p.dive, p.headUnder); the finds are generated by gen.seabed (world/gen.js) and drawn by
// three/seabed3d.js; this file says what can be reached, and what picking it gives.
//
//   finds come from game.world.gen.seabed(cx, cy) → { finds: [{ kind, key, x, y, bed, tall?, yaw? }] } (cx wrapped);
//     kind: 'seashell' | 'seaweed' | 'oyster' | 'mussel' | 'sunken_chest'; key: `${kind}:${tx},${ty}`
//   chunk-delta fields: d.dived[key] = real day it was picked (shell, seaweed, oyster, mussel; they regrow, REGROW), and
//     d.opened[key] = who opened it (sunken chest; never regrows, drawn open). Both are saved and synced like any field
//   the real day is game.days.realDay (the same day as carry.js today())
//   shells and seaweed are first come (two divers racing may both get one, like flowers). Oysters, mussels and sunken
//     chests go through a host-resolved claim: CLAIMS.shellfish and CLAIMS.sunk (claims.js, registered here); alone, as
//     the host or as the world server (game.barrow.decides()) they are called directly and granted at once
//   loot is rolled from ihash(the find's tile, the world's seed, the day it was picked), so every peer rolls the same
//   a local pick hides the find at once: game.view3d.world?.seabed?.hide?.(key) (seabed3d.js); a remote one shows when
//     its chunk syncs (seabed3d.js checks d.dived and d.opened)
//   items given: seashell, pearl, seaweed, mussel (items.js); xp: game.skills.gain('diving', n) (progress.js)
import { t } from './i18n.js';
import { ITEMS } from './items.js';
import { CHUNK } from './world/gen.js';
import { WATER_Y, nearX, wrapIndex } from './world/planet.js';
import { ihash } from './util.js';
import { CLAIMS } from './claims.js';
import { Profile } from './accounts.js';
import { hud } from './ui/hud.js';
import { Audio } from './audio.js';
import { reportFault } from './faults.js';

// Real days until a picked find is back (sunken chests never come back: they stay open)
export const REGROW = { seashell: 3, seaweed: 2, mussel: 5, oyster: 7 };
const KEEP_DAYS = Math.max(...Object.values(REGROW));   // (older picks are pruned from d.dived: they are back anyway)

// Is find o (from gen.seabed) taken today in chunk delta d? Sunken chests are never hidden (only drawn open)
export const takenNow = (d, o, day) => {
  const r = REGROW[o.kind], at = d?.dived?.[o.key];
  return r !== undefined && at !== undefined && at >= day - r;
};

// Reach: within REACH tiles in plan of the diver and REACH_UP m of the diver's height (WATER_Y - SWIM_EYE - sink - dive,
// three/engine.js feetY): from the surface a shell 2 m down is reached, a pearl 10 m down is not
const REACH = 2.2, REACH_UP = 1.8, SWIM_EYE = 0.7;
// What each find is to aim at: [half width, height] of its box over the bed (seaweed: as tall as it grows)
const SIZE = { seashell: [0.22, 0.25], seaweed: [0.3, 1], oyster: [0.28, 0.3], mussel: [0.22, 0.25], sunken_chest: [0.55, 0.75] };
const TEXT = { seashell: 'dive.pick_shell', seaweed: 'dive.cut_seaweed', oyster: 'dive.open_oyster', mussel: 'dive.open_mussel', sunken_chest: 'dive.open_chest' };
const XP = { seashell: 2, seaweed: 1, mussel: 3, oyster: 6, sunken_chest: 25 };   // (diving xp per find, §2.8)
const CLAIM_OF = { oyster: 'shellfish', mussel: 'shellfish', sunken_chest: 'sunk' };
const PEARL = { oyster: 0.25, mussel: 0.05 };   // (plus skills.bonus('diving'): 3 % per level)
const ASK_WAIT = 10;   // s: a guest's claim of a find is not asked again meanwhile (barrow.js answers or gives up in 8)
// A sunken chest: coins always, and each of these with its chance and amount [min, max] (about 4 kg at most)
const CHEST_COINS = [60, 240];
const CHEST = [['moneda_antigua', 0.6, 1, 3], ['pearl', 0.35, 1, 1], ['lingote_cobre', 0.4, 1, 3], ['lingote_hierro', 0.25, 1, 2], ['cuerda', 0.3, 2, 2], ['fosil_ambar', 0.1, 1, 1]];
const SALT = { seashell: 911, seaweed: 912, oyster: 913, mussel: 914, sunken_chest: 915 };

const me = () => Profile.id || 'me';
const kindOf = key => (typeof key === 'string' ? key.slice(0, key.indexOf(':')) : '');
const tileOf = key => key.slice(key.indexOf(':') + 1).split(',').map(Number);
// (the finds of a chunk, by its wrapped index, as every peer asks for them)
const findsOf = (g, cx, cy) => g.world?.gen?.seabed?.(wrapIndex(cx, CHUNK), cy)?.finds || [];
// A pick written into the chunk: the day, and the picks that have regrown anyway pruned
function mark(d, key, day) {
  const m = (d.dived ||= {});
  m[key] = day;
  for (const [k, v] of Object.entries(m)) if (!(v >= day - KEEP_DAYS)) delete m[k];
}
// A number from 0 to 1 for roll i of find key, picked on day: the same on every peer
function roll(g, key, i, day = 0) {
  const [tx, ty] = tileOf(key), seed = g.world?.gen?.seed | 0;
  return ihash(tx, ty, (seed + (SALT[kindOf(key)] || 917) * 31 + i * 131 + day * 7919) | 0);
}
const between = (r, lo, hi) => lo + Math.min(hi - lo, Math.floor(r * (hi - lo + 1)));

// ---------- the host's word (claims.js): checked against the world's own finds, never only the guest's word ----------
// (is there such a find in that chunk, of that kind?)
function exists(g, k, key, kinds) {
  if (typeof key !== 'string' || !kinds.includes(kindOf(key))) return false;
  const [cx, cy] = k.split(',').map(Number);
  return findsOf(g, cx, cy).some(o => o.key === key);
}
// An oyster or a mussel: free if it has regrown since it was last picked. extra.day: the day of the pick (the loot's roll)
CLAIMS.shellfish = (g, c, d, k, extra) => {
  if (!exists(g, k, c.key, ['oyster', 'mussel'])) return false;
  const day = g.days?.realDay ?? 0;
  if (takenNow(d, { kind: kindOf(c.key), key: c.key }, day)) return false;
  mark(d, c.key, day);
  extra.day = day;
  return true;
};
// A sunken chest: once, ever
CLAIMS.sunk = (g, c, d, k) => {
  if (!exists(g, k, c.key, ['sunken_chest']) || d.opened?.[c.key]) return false;
  (d.opened ||= {})[c.key] = typeof c.by === 'string' && c.by ? c.by.slice(0, 64) : true;
  return true;
};

export class Dive {
  constructor(game) {
    this.game = game;
    this.asked = new Map();   // (a guest) find key → game.time its claim was asked (not offered again until answered)
  }
  reset() { this.asked.clear(); }
  today() { return this.game.days?.realDay ?? 0; }
  // Where the diver is, in height (as engine.js feetY: what the reach is measured from)
  diverY(p) { return WATER_Y - SWIM_EYE - (p.sink || 0) - (p.dive || 0); }
  // The finds within reach of p, each { o, cx, cy, x (o.x next to p, across the planet's seam) }, untaken and in reach
  reachable(p) {
    const g = this.game, w = g.world, out = [];
    if (!p?.swim || g.scene !== w || !w?.gen?.seabed) return out;
    const y = this.diverY(p), day = this.today(), now = g.time;
    for (const [key, at] of this.asked) if (!(now - at < ASK_WAIT)) this.asked.delete(key);
    const cx0 = Math.floor((p.x - REACH) / CHUNK), cx1 = Math.floor((p.x + REACH) / CHUNK);
    const cy0 = Math.floor((p.y - REACH) / CHUNK), cy1 = Math.floor((p.y + REACH) / CHUNK);
    for (let cy = cy0; cy <= cy1; cy++) for (let cx = cx0; cx <= cx1; cx++) {
      const finds = findsOf(g, cx, cy);
      if (!finds.length) continue;
      const d = w.delta(cx, cy);
      for (const o of finds) {
        const x = nearX(o.x, p.x);
        if (Math.hypot(x - p.x, o.y - p.y) > REACH || !(Math.abs(y - o.bed) < REACH_UP)) continue;
        if (!this.free(o, d, day) || this.asked.has(o.key)) continue;
        out.push({ o, cx, cy, x });
      }
    }
    return out;
  }
  free(o, d, day) { return o.kind === 'sunken_chest' ? !d?.opened?.[o.key] : !takenNow(d, o, day); }
  offer(f) { return { text: t(TEXT[f.o.kind] || 'dive.pick_shell'), run: () => this.take(f) }; }

  // game.aimTargets asks every system: while swimming in the world, the finds in reach, each a box from the drawn bed up
  // (absolute heights: the finds sit on the bed, not on groundY's water surface)
  aimables(p, sc, box) {
    if (sc !== this.game.world) return null;
    const list = this.reachable(p);
    if (!list.length) return null;
    const view = this.game.view3d;
    return list.map(f => {
      const { o, x } = f, S = SIZE[o.kind] || SIZE.seashell;
      let y0 = view?.bedY?.(x, o.y);
      if (!Number.isFinite(y0)) y0 = o.bed;
      const b = box(x, o.y, S[0], S[0], y0, y0 + (o.kind === 'seaweed' && o.tall > 0 ? o.tall : S[1]));
      b.abs = true;
      const a = { kind: 'sys', find: o.key, box: b, act: () => this.offer(f) };
      // (a sunken chest is outlined as its model, as seabed3d.js draws it a little sunk in the sand; its aim box stays)
      if (o.kind === 'sunken_chest') { a.model = { name: 'treasure:0', x, y: o.y, yaw: o.yaw || 0, lift: y0 - 0.08 }; a.keepBox = true; }
      return a;
    });
  }
  // The swimming-E fallback without a mouse (game.js nearest): the nearest find in reach, as { text, run }, or null
  action(p, sc) {
    if (sc !== this.game.world) return null;
    const y = this.diverY(p);
    let best = null, bd = Infinity;
    for (const f of this.reachable(p)) {
      const dd = Math.hypot(f.x - p.x, f.o.y - p.y, y - f.o.bed);
      if (dd < bd) { bd = dd; best = f; }
    }
    return best ? this.offer(best) : null;
  }

  // ---------- picking ----------
  take(f) {
    const g = this.game, w = g.world, p = g.player, { o, cx, cy } = f;
    if (!w || !p?.swim || g.scene !== w) return;
    const d = w.delta(cx, cy, true), day = this.today();
    if (!this.free(o, d, day)) return;
    const kind = CLAIM_OF[o.kind];
    if (!kind) {   // (a shell or seaweed: first come)
      mark(d, o.key, day);
      w.note(cx, cy);
      this.got(o, day);
      return;
    }
    const B = g.barrow, k = `${wrapIndex(cx, CHUNK)},${cy}`;
    if (!B || B.decides()) {
      // (alone, the host or the world server: the word is this game's, now; a claim() would never be answered here)
      const extra = {};
      let ok = false;
      try { ok = !!CLAIMS[kind](g, { by: me(), k: kind, key: o.key }, d, k, extra); } catch (e) { reportFault(e, 'Dive.claim'); }
      if (ok) { w.note(cx, cy); this.got(o, Number.isFinite(extra.day) ? extra.day : day); } else this.late();
      return;
    }
    // (a guest: the host's word; the loot only once it says yes)
    if (B.waiting(kind)) return;
    this.asked.set(o.key, g.time);
    B.claim(kind, k, { key: o.key }, v => {
      // (taken: still not offered for ASK_WAIT more, until the host's d.dived or d.opened comes in the next sync; a second
      // E meanwhile would ask again and hear "someone got there first" about its own find)
      if (v?.ok) { this.asked.set(o.key, g.time); this.got(o, Number.isFinite(v.day) ? v.day : this.today()); }
      else { this.asked.delete(o.key); this.late(); }
    });
  }
  late() { hud.toast(t('dive.too_late'), 'warn'); Audio.error(); }
  // What a find gives (rolled from its key and day), into the inventory (what does not fit, thrown out by the player)
  got(o, day) {
    const g = this.game, key = o.key;
    try { g.view3d?.world?.seabed?.hide?.(key); } catch (e) { reportFault(e, 'Seabed.hide'); }
    const items = [];
    if (o.kind === 'seashell') items.push(['seashell', 1]);
    else if (o.kind === 'seaweed') items.push(['seaweed', 1 + (roll(g, key, 0, day) < 0.5 ? 1 : 0)]);
    else if (o.kind === 'oyster' || o.kind === 'mussel') {
      items.push([o.kind === 'oyster' ? 'seashell' : 'mussel', 1]);
      const pearl = roll(g, key, 1, day) < PEARL[o.kind] + (g.skills?.bonus?.('diving') || 0);
      if (pearl) { items.push(['pearl', 1]); hud.toast(t('dive.pearl'), 'good'); }
      else if (o.kind === 'oyster') g.gather?.float?.(t('dive.no_pearl'), '#cfe3ea');   // (a mussel seldom has one: no word)
    } else if (o.kind === 'sunken_chest') {
      const coins = between(roll(g, key, 0), CHEST_COINS[0], CHEST_COINS[1]);
      CHEST.forEach(([id, chance, lo, hi], i) => { if (roll(g, key, 2 + i * 2) < chance) items.push([id, between(roll(g, key, 3 + i * 2), lo, hi)]); });
      g.addMoney?.(coins);
      g.gather?.float?.(`+${coins} 🪙`, '#ffe08a');
      hud.toast(t('dive.chest_name'), 'good');
      Audio.unlock();
      g.stats?.add?.('cofres', 1);
    }
    for (const [id, n] of items) this.give(id, n);
    if (o.kind !== 'sunken_chest') { try { g.nature?.harvested?.(o.kind); } catch (e) { reportFault(e, 'Dive.nature'); } }   // (its nature book page: Known, Plan G-2)
    try { g.skills?.gain?.('diving', XP[o.kind] || 0); } catch (e) { reportFault(e, 'Dive.xp'); }
    if (CLAIM_OF[o.kind]) g.onSave?.();   // (a claimed one, a pearl or a chest's coins: saved now)
  }
  give(id, n) {
    const g = this.game;
    if (!ITEMS[id] || !(n > 0)) return;   // (an item of a newer version, or of a track not merged yet: nothing)
    const left = g.inv.add(id, n);
    for (let i = left; i < n; i++) g.gather?.collected?.(id);
    if (left > 0) g.gather?.throwOut?.(id, left);
  }
}
